const fragmentContainer = fragmentElement.querySelector(
  ".global-whatsapp-forwarding"
);
const whatsappForwardingElement = fragmentContainer.querySelector(
  "#whatsapp-forwarding"
);

if (whatsappForwardingElement) {
  const handleWhatsAppForwarding = () => {
    const rawPhone = configuration.forwardingNumber || "";
    let phone = rawPhone.replace(/\D/g, "").replace(/^0+/, "");

    if (!phone.startsWith("55")) {
      phone = "55" + phone;
    }

    const message = configuration.forwardingMessage;

    if (phone.length >= 12) {
      let url = `https://wa.me/${phone}`;
      if (message) {
        url += `?text=${encodeURIComponent(message)}`;
      }
      window.open(url, "_blank");
    }
  };

  whatsappForwardingElement.addEventListener("click", handleWhatsAppForwarding);

  whatsappForwardingElement.addEventListener("keydown", (event) => {
    if (event.key === "Enter" || event.keyCode === 13) {
      handleWhatsAppForwarding();
    }
  });

  whatsappForwardingElement.setAttribute("tabindex", "0");
  whatsappForwardingElement.style.cursor = "pointer";
};

