js:
const container = fragmentElement.querySelector('.number-list-and-buttons');

// Button
if (!document.body.classList.contains('has-edit-mode-menu')) {
    setTimeout(function() {
        const primaryButtons = container.querySelectorAll('.primary-button');

        primaryButtons.forEach(primaryButton => {
            primaryButton.addEventListener('click', (event) => {
                const group = primaryButton.getAttribute('group');

                const allButtons = container.querySelectorAll('button');
                allButtons.forEach(btn => btn.style.display = 'none');

                const secondaryButtons = container.querySelectorAll(`a.secondary-button[group="${group}"]`);
                secondaryButtons.forEach(btn => {
                    btn.style.display = 'inline-flex';
                });
            });
        });
    });
}

// Title
if (!document.querySelector("h1")) {
    const firstTitle = document.querySelector(".number-list-and-buttons .title");

    if (firstTitle) {
        const h1 = document.createElement("h1");

        [...firstTitle.attributes].forEach(attr => {
            h1.setAttribute(attr.name, attr.value);
        });

        h1.innerHTML = firstTitle.innerHTML;

        firstTitle.replaceWith(h1);
    }
};

