css:
.number-list-and-imagem *{
    box-sizing: border-box;
}

.number-list-and-imagem {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    width: 100%;
    padding: 30px 0;
    overflow: hidden;
    position: relative;
}

.number-list-and-imagem 
    .main-content{
        display: flex;
        width: 100%;
        max-width: 1200px;
        justify-content: space-between;
        align-items: center;
        gap: 90px;
}

.number-list-and-imagem 
    .main-content
        .number-list{
            display: flex;
            flex-direction: column;
            width: 587px;
            gap: 20px;
}

.number-list-and-imagem 
    .main-content
        .number-list.multiple-images-2,
.number-list-and-imagem 
    .main-content
        .number-list.multiple-images-4{
            width: 355px;
}

.number-list-and-imagem 
    .main-content
        .number-list.multiple-images-3{
            width: 385px;
}

.number-list-and-imagem 
    .main-content
        .number-list
            .title{
                display: inline-flex;
                color: #2C2C2C;
                max-width: 512px;
}

.number-list-and-imagem 
    .main-content
        .number-list
            .description{
                display: inline-flex;
                font-size: 20px;
                line-height: 26px;
                font-family: 'oxygen-regular';
                color: var(--gray);
}


.number-list-and-imagem 
    .main-content
        .list-content {
            display: flex;
            flex-direction: column;
            gap: 14px;
}

.number-list-and-imagem 
    .numbered-item{
        display: flex;
        flex-direction: row;
        align-items: start;
        width: 100%;
        gap: 15px;
}

.number-list-and-imagem 
    .numbered-item
        .numbered-item-number{
            display: inline-flex;
            min-width: 38px;
            min-height: 38px;
            justify-content: center;
            align-items: center;
            padding: 0 15px;
            background: var(--primary);
            border-radius: 50%;
            font-size: 20px;
            font-family: 'oxygen-bold';
            line-height: 26px;
            color: var(--white);
}

.number-list-and-imagem 
    .numbered-item
        .numbered-item-text{
            font-size: 16px;
            line-height: 26px;
            font-family: 'oxygen-regular';
            color: var(--black);
}

.number-list-and-imagem 
    .image-content {
        display: grid;
}

.number-list-and-imagem 
    .image-content.multiple-images-2 {
        grid-template-columns: repeat(2, 1fr);
        gap: 73px;
}

.number-list-and-imagem 
    .image-content.multiple-images-3 {
        grid-template-columns: repeat(3, 1fr);
        gap: 35px;
}

.number-list-and-imagem 
    .image-content.multiple-images-4 {
        grid-template-columns: repeat(2, 1fr);
        gap: 43px;
}

.number-list-and-imagem 
    .image-content.multiple-images-2 
        .image-container{
            width: 338px;
            min-height: 338px!important;
}

.number-list-and-imagem 
    .image-content.multiple-images-3 
        .image-container{
            width: 210px;
            min-height: 207px!important;
}

.number-list-and-imagem 
    .image-content.multiple-images-4 
        .image-container {
            width: 232px;
            min-height: 232px!important;
}

.number-list-and-imagem 
    .image-container{
        display: flex;    
        align-items: end;
        width: 400px;
        min-height: 400px!important;
        mix-blend-mode: multiply;
        border-radius: 19px;
        overflow: hidden;
        position: relative;
}

.number-list-and-imagem 
    .image-content
        .image-container
            img{
                width: 100%;
                height: 100%;
                border-radius: 19px;
}

.number-list-and-imagem 
    .image-container
        .image-link {
            display: block;
            padding: 40px 32px;

            line-height: 38px;
            color: var(--white);
            text-decoration: underline;
            font-family: 'oxygen-regular';

            overflow: hidden;
            text-overflow: ellipsis;
            max-width: 100%;
            position: absolute;
}

.number-list-and-imagem 
        .image-link,
.number-list-and-imagem 
    .image-content.multiple-images-2
        .image-link {
            font-size: 32px;
}

.number-list-and-imagem 
    .image-content.multiple-images-3
        .image-link,
.number-list-and-imagem 
    .image-content.multiple-images-4
        .image-link {
            font-size: 22px;
}

.number-list-and-imagem 
    .image-container
        .image-link:hover {
            color: var(--white);
            text-decoration: underline;
            cursor: pointer;
}

