            gap: 20px;
    }


    .number-list-and-imagem 
        .main-content {
            max-width: 376px;
            flex-direction: column;
            align-items: center;
            gap: 48px;
    }

    .number-list-and-imagem 
        .main-content 
            .number-list{
                width: 100%!important;
                align-items: start;
                gap: 24px;
    }
    .number-list-and-imagem 
        .main-content 
            .number-list
                .title{
                   font-size: 24px;
