$(document).ready(function () {
  $('#tabButtons ul li').click(function (e) {
    e.preventDefault();
    $('#tabButtons ul li a').removeClass('btn-relatorios-sec'); //remove de todos os botões
    $('#tabButtons ul li a').addClass('btn-relatorios-pri');
    $(this).children().addClass('btn-relatorios-sec'); //adiciona a classe no botão clicado

    const tabName = $(this).attr('data-tab');

    $('#tabContent .tab').removeClass('active'); //remove de todas as tabs
    $('#tabContent #' + tabName).addClass('active'); //adiciona na classe clicada
  });

  $('.filter-item').click(function (e) {
    var label = $(this).text();
    $('#btn-filter-mobile').text(label);

    $('#tabButtons ul li a').removeClass('btn-relatorios-sec'); //remove de todos os botões
    $('#tabButtons ul li a').addClass('btn-relatorios-pri');

    const tabName = $(this).attr('data-tab');

    $("#"+tabName).addClass('btn-relatorios-sec'); //adiciona a classe no botão clicado

    $('#tabContent .tab').removeClass('active'); //remove de todas as tabs
    $('#tabContent #' + tabName).addClass('active'); //adiciona na classe clicada

  });
});;

