fragmentElement.style.justifyContent = 'center';

setTimeout(function() {
    const titleContainer = fragmentElement.querySelector('.global-icon-more-text-grid');
    if(titleContainer && configuration.itemsPerColumn != "line"){
        titleContainer.style.display = 'grid';
    }else if(titleContainer){
        titleContainer.style.display = 'flex';
    }
}, 500);;

