.global-dropzone-more-text 
    .dropzone-container, 
.global-dropzone-more-text 
    .text-container {
        width: 100%; 
}

.global-dropzone-more-text 
    .text-container {
        display: flex;
        flex-direction: column;
}

/* Title and Text */
.global-dropzone-more-text 
    .global-editable-title {
        display: inline-block;
        overflow-wrap: break-word;
        width: 100%;
}

.global-dropzone-more-text 
    .global-editable-text {
        display: inline-block;
        width: 100%;
        overflow-wrap: break-word;
        color: var(--black);
        font-family: "oxygen-regular";
}

.global-dropzone-more-text 
    .global-editable-text strong{
        font-family: "oxygen-bold";
        color: var(--dark);
}

.global-dropzone-more-text 
    .global-editable-text a {
        font-family: "oxygen-bold";
        color: var(--primary);
        text-decoration: underline;
}

/* Button */
.global-dropzone-more-text
    .editable-button{
        display: inline-block;
        width: fit-content;
        height: fit-content;
        border-radius: 7px;
        padding: 14px 18px;

        font-family: "oxygen-bold";
        text-decoration: none;
        transition: all .2s ease-in-out;
}

.global-dropzone-more-text
    .editable-button.default{
        background: var(--primary);
        color: var(--white);
        border: inherit;

        font-size: 16px;
        line-height: 14px;
}

.global-dropzone-more-text
    .editable-button.outline{
        border: 1px solid var(--primary);
        color: var(--primary);
        background: transparent;

        font-size: 20px;
        line-height: 14px;
}

.global-dropzone-more-text 
    .editable-button.link {
        font-size: 16px;
        font-family: 'oxygen-regular';
        color: var(--primary);
        padding: 0;
        text-decoration: underline;
}

body:not(.has-edit-mode-menu) 
    .global-dropzone-more-text 
        .editable-button.link::before {
            display: inline-block;
            content: '>';
            font-size: 20px;
            line-height: 14px;
            font-family: 'oxygen-regular';
            color: #0435AC;
            margin-right: 4px;
            text-decoration: underline transparent;
}


.global-dropzone-more-text
    .editable-button.default:hover {
        background: var(--white);
        border: 1px solid var(--primary);
        color: var(--primary);
}

.global-dropzone-more-text
    .editable-button.outline:hover {
        color: var(--lighter);
        background-color: var(--primary);
}

.global-dropzone-more-text
