const fragmentContainer = fragmentElement.querySelector('.global-plans-card-grid');
const carousel = fragmentContainer.querySelector('div.container');
const carouselPrevButton = fragmentContainer.querySelector('button.prev');
const carouselNextButton = fragmentContainer.querySelector('button.next');

const items = carousel.querySelectorAll('.global-plan-card');
const gapSize = 20; 

if (items.length <= 1) {
    fragmentContainer.querySelector('.controller-container').style.display = 'none';
    carousel.style.justifyContent = 'center';
    return;
}

let itemWidth = items[0].offsetWidth + gapSize;
let currentTranslate = 0;
let maxTranslate = calculateMaxTranslate();

carouselPrevButton.addEventListener('click', () => moveCarousel(-1));
carouselNextButton.addEventListener('click', () => moveCarousel(1));

updateButtonStates();

function moveCarousel(direction) {
    const nextTranslate = currentTranslate + direction * -itemWidth;

    if (nextTranslate > 0) {
        currentTranslate = 0;
    } else if (nextTranslate < maxTranslate) {
        currentTranslate = maxTranslate;
    } else {
        currentTranslate = nextTranslate;
    }

    carousel.style.transform = `translateX(${currentTranslate}px)`;
    updateButtonStates();
}

function calculateMaxTranslate() {
    const totalWidth = itemWidth * items.length;
    const visibleWidth = carousel.offsetWidth;
    return Math.min(0, visibleWidth - totalWidth);
}

function updateButtonStates() {
    carouselPrevButton.disabled = currentTranslate === 0;
    carouselNextButton.disabled = currentTranslate <= maxTranslate;
}

window.addEventListener('resize', () => {
    itemWidth = items[0].offsetWidth + gapSize;
    maxTranslate = calculateMaxTranslate();

    if (currentTranslate < maxTranslate) {
        currentTranslate = maxTranslate;
    }

    carousel.style.transform = `translateX(${currentTranslate}px)`;
    updateButtonStates();
});


// Image Alt
const spans = fragmentContainer.querySelectorAll('.background-alt');

spans.forEach(span => {
    const id = span.id;
    const div = document.querySelector(`.background-image[id="${id}"]`);

    if (div) {
        div.setAttribute('alt', span.textContent.trim());
    }
});;

