body.theme-contrast .clip-path, body.theme-contrast .clipBox, body.theme-contrast .bgShadow {
    background-color: var(--white-base)!important;
}
.clip-path {
      height: 50px;
      width: 100%;
	    top: 0;
    	left: 0;
    	position: absolute;
      clip-path: inset(0% 0% 0% 0% round 0px 0px 50px 0px);
		margin-top:-2px;
	/* Esta sintaxe é: inset(top right bottom left round top-left top-right bottom-right bottom-left) */
}
/*background shadow*/
.clipBox {
    position: relative;
}
.clipBox .bgShadow {
    height: 50px;
	  width: 100%;   
}
.clip-pathDL {
      height: 50px;
      width: 100%;
	    top: 0;
    	left: 0;
    	position: absolute;
	    clip-path: inset(0% 0% 0% 0% round 0px 0px 50px 50px);
	/* Esta sintaxe é: inset(top right bottom left round top-left top-right bottom-right bottom-left) */
}
.clip-pathL {
      height: 50px;
      width: 100%;
	    top: 0;
    	left: 0;
    	position: absolute;
      clip-path: inset(0% 0% 0% 0% round 0px 0px 0px 50px);
	/* Esta sintaxe é: inset(top right bottom left round top-left top-right bottom-right bottom-left) */
}

